const alertIn = $('RackWatch Alert')?.item?.json?.body || $('RackWatch Alert')?.item?.json || $('RackWatch Diagnose Webhook')?.item?.json?.body || $('RackWatch Diagnose Webhook')?.item?.json || {};
const snap = $json || {};
const alert = {
  title: String(alertIn.title || 'Alerta RackWatch'),
  message: String(alertIn.message || ''),
  severity: String(alertIn.severity || 'warning'),
  source: String(alertIn.source || 'rackwatch'),
  host: String(alertIn.host || snap.instance || 'casaos'),
  service: String(alertIn.service || ''),
  fingerprint: String(alertIn.fingerprint || '')
};

const containers = Array.isArray(snap.containers) ? snap.containers : [];
const topCpu = [...containers]
  .filter(c => c.cpu_percent != null && c.cpu_percent > 0)
  .sort((a, b) => (b.cpu_percent || 0) - (a.cpu_percent || 0))
  .slice(0, 5)
  .map(c => ({ name: c.name, cpu: c.cpu_percent.toFixed(1) + '%' }));

const fmtBytes = (bytes) => {
  if (!bytes) return null;
  const gb = bytes / (1024 * 1024 * 1024);
  if (gb >= 1) return gb.toFixed(1) + ' GB';
  const mb = bytes / (1024 * 1024);
  return mb.toFixed(0) + ' MB';
};

const topRam = [...containers]
  .filter(c => (c.memory_bytes && c.memory_bytes > 0) || (c.memory_percent && c.memory_percent > 0))
  .sort((a, b) => (b.memory_bytes || b.memory_percent || 0) - (a.memory_bytes || a.memory_percent || 0))
  .slice(0, 5)
  .map(c => ({
    name: c.name,
    ram: fmtBytes(c.memory_bytes) || (c.memory_percent != null ? c.memory_percent.toFixed(0) + '%' : '—'),
    pct: c.memory_percent != null ? c.memory_percent.toFixed(0) + '%' : null
  }));

const isResource = ['cpu', 'ram', 'disk', 'container_cpu', 'container_ram'].includes(alert.source) || ['cpu', 'ram', 'disk'].includes(alert.service);
const isContainer = alert.source === 'container' && alert.service && !['cpu', 'ram', 'disk'].includes(alert.service);

return [{
  json: {
    alert,
    service: isContainer ? alert.service : (topCpu[0]?.name || 'rackwatch'),
    fetchLogs: isContainer,
    topCpu,
    topRam,
    isResource,
    snapshot: snap
  }
}];

