const prep = $('Preparar alerta').item.json;
const a = prep.alert;
const topCpu = prep.topCpu || [];
const topRam = prep.topRam || [];
const content = String($json.message?.content || '');

const esc = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const icon = a.severity === 'critical' ? '🔴' : a.severity === 'warning' ? '⚠️' : 'ℹ️';

let text = `${icon} <b>RackWatch · ${esc(a.severity.toUpperCase())}</b>\n`;
text += `<b>${esc(a.title)}</b>\n`;
if (a.message) {
  text += `<i>${esc(a.message)}</i>\n\n`;
}

text += `🖥️ <b>Host:</b> <code>${esc(a.host || 'casaos')}</code>\n`;
if (a.service && !['cpu', 'ram', 'disk'].includes(a.service)) {
  text += `📦 <b>Servicio:</b> <code>${esc(a.service)}</code>\n`;
}

if (topCpu.length > 0 && (a.source === 'cpu' || a.source === 'container_cpu' || prep.isResource || a.title.toLowerCase().includes('cpu'))) {
  text += `\n🔥 <b>Top Contenedores por CPU:</b>\n`;
  for (const c of topCpu) {
    text += `  • <code>${esc(c.name)}</code>: <b>${c.cpu}</b>\n`;
  }
}

if (topRam.length > 0 && (a.source === 'ram' || a.source === 'container_ram' || prep.isResource || a.title.toLowerCase().includes('ram') || a.title.toLowerCase().includes('mem'))) {
  text += `\n🧠 <b>Top Contenedores por RAM:</b>\n`;
  for (const c of topRam) {
    const p = c.pct ? ` (${c.pct})` : '';
    text += `  • <code>${esc(c.name)}</code>: <b>${c.ram}${p}</b>\n`;
  }
}

if (content && !content.includes('error')) {
  text += `\n💡 <b>Diagnóstico IA:</b>\n${esc(content.trim())}\n`;
}

text += `\n🏷️ <code>${esc(a.fingerprint || 'rackwatch')}</code>`;

return [{ json: { text: text.slice(0, 3950), fingerprint: a.fingerprint } }];

const m = $json.message || $json.edited_message || {};
const text = String(m.text || '').trim();
const chatId = m.chat?.id;
const user = m.from?.username || m.from?.first_name || 'usuario';

const lower = text.toLowerCase();
let command = 'custom';
if (['/start', 'start', '/help', 'help', '/ayuda', 'ayuda'].includes(lower)) {
  command = 'help';
} else if (['/status', 'status', '/estado', 'estado'].includes(lower)) {
  command = 'status';
} else if (['/cpu', 'cpu'].includes(lower)) {
  command = 'cpu';
} else if (['/ram', 'ram', '/memoria', 'memoria', '/mem'].includes(lower)) {
  command = 'ram';
} else if (['/alertas', 'alertas', '/alerts', 'alerts'].includes(lower)) {
  command = 'alerts';
}

return [{
  json: {
    chatId,
    user,
    text: text || '/status',
    command,
    isDirectCommand: command !== 'custom'
  }
}];

