const q = $('Preparar consulta Telegram').item.json;
const snap = $('RackWatch Snapshot · Chat').item.json || {};
const alerts = Array.isArray($('RackWatch Alertas recientes').item.json) ? $('RackWatch Alertas recientes').item.json : [];
const ollamaContent = String($json.message?.content || '');

const esc = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const host = (snap.hosts && snap.hosts[0]) || {};
const containers = Array.isArray(snap.containers) ? snap.containers : [];
const zfs = Array.isArray(snap.zfs) ? snap.zfs : [];

const fmtBytes = (bytes) => {
  if (!bytes) return '—';
  const gb = bytes / (1024 * 1024 * 1024);
  if (gb >= 1) return gb.toFixed(1) + ' GB';
  const mb = bytes / (1024 * 1024);
  return mb.toFixed(0) + ' MB';
};

const topCpu = [...containers]
  .filter(c => c.cpu_percent != null && c.cpu_percent > 0)
  .sort((a, b) => (b.cpu_percent || 0) - (a.cpu_percent || 0))
  .slice(0, 5);

const topRam = [...containers]
  .filter(c => (c.memory_bytes && c.memory_bytes > 0) || (c.memory_percent && c.memory_percent > 0))
  .sort((a, b) => (b.memory_bytes || b.memory_percent || 0) - (a.memory_bytes || a.memory_percent || 0))
  .slice(0, 5);

let text = '';

if (q.command === 'help') {
  text = `🤖 <b>RackWatch · Comandos Homelab</b>\n\n` +
    `📊 <b>/status</b> o <b>/estado</b> — Resumen completo del sistema\n` +
    `🔥 <b>/cpu</b> — Consumo de CPU y top contenedores\n` +
    `🧠 <b>/ram</b> — Consumo de memoria RAM detallado\n` +
    `🚨 <b>/alertas</b> — Alertas activas y recientes\n` +
    `❓ O escribe cualquier pregunta o consulta en lenguaje natural (ej: <i>¿por qué subió la CPU?</i>, <i>diagnostica plex</i>) para que el modelo IA local lo analice.`;
} else if (q.command === 'status') {
  const statusIcon = host.status === 'ok' ? '🟢' : host.status === 'warning' ? '🟡' : '🔴';
  text = `${statusIcon} <b>RackWatch · Estado del Homelab</b>\n` +
    `Host: <code>${esc(host.name || snap.instance || 'casaos')}</code>\n\n` +
    `💻 <b>Recursos Host:</b>\n` +
    `• CPU: <b>${host.cpu_percent != null ? host.cpu_percent.toFixed(0) + '%' : '—'}</b>\n` +
    `• RAM: <b>${host.ram_percent != null ? host.ram_percent.toFixed(0) + '%' : '—'}</b> (${fmtBytes(host.ram_used_bytes)} / ${fmtBytes(host.ram_total_bytes)})\n` +
    `• Disco: <b>${host.disk_percent != null ? host.disk_percent.toFixed(0) + '%' : '—'}</b>\n` +
    (host.load1 != null ? `• Load: <code>${host.load1}</code>` : '') +
    (host.uptime_seconds ? ` · Uptime: <code>${(host.uptime_seconds / 86400).toFixed(1)}d</code>\n\n` : '\n\n') +
    `🐳 <b>Contenedores (${containers.length}):</b>\n`;

  const down = containers.filter(c => c.severity === 'error');
  if (down.length > 0) {
    text += `⚠️ <b>Caídos/Error (${down.length}):</b> ` + down.map(c => `<code>${esc(c.name)}</code>`).join(', ') + `\n`;
  } else {
    text += `✅ Todos los contenedores operativos.\n`;
  }

  if (topCpu.length > 0) {
    text += `🔥 <b>Top CPU:</b> ` + topCpu.slice(0, 3).map(c => `<code>${esc(c.name)}</code> (${c.cpu_percent.toFixed(0)}%)`).join(', ') + `\n`;
  }
  if (topRam.length > 0) {
    text += `🧠 <b>Top RAM:</b> ` + topRam.slice(0, 3).map(c => `<code>${esc(c.name)}</code> (${fmtBytes(c.memory_bytes)})`).join(', ') + `\n`;
  }

  if (zfs.length > 0) {
    text += `\n🛡️ <b>ZFS Pools:</b>\n` + zfs.map(z => `• <code>${esc(z.name)}</code>: ${esc(z.health)} (${z.capacity_percent || 0}% usado)`).join('\n') + `\n`;
  }

  text += `\n🚨 <b>Alertas recientes:</b> ${alerts.length ? alerts.length + ' registradas' : '0 activas'}`;
} else if (q.command === 'cpu') {
  text = `🔥 <b>RackWatch · Monitoreo de CPU</b>\n` +
    `Host CPU: <b>${host.cpu_percent != null ? host.cpu_percent.toFixed(1) + '%' : '—'}</b>` +
    (host.load1 != null ? ` (Load: ${host.load1})` : '') + `\n\n` +
    `📊 <b>Top Contenedores por CPU:</b>\n`;
  if (topCpu.length) {
    for (const c of topCpu) {
      text += `• <code>${esc(c.name)}</code>: <b>${c.cpu_percent.toFixed(1)}%</b>\n`;
    }
  } else {
    text += `<i>Sin datos de CPU de contenedores en este ciclo.</i>\n`;
  }
} else if (q.command === 'ram') {
  text = `🧠 <b>RackWatch · Monitoreo de RAM</b>\n` +
    `Host RAM: <b>${host.ram_percent != null ? host.ram_percent.toFixed(1) + '%' : '—'}</b> (${fmtBytes(host.ram_used_bytes)} / ${fmtBytes(host.ram_total_bytes)})\n\n` +
    `📊 <b>Top Contenedores por Memoria:</b>\n`;
  if (topRam.length) {
    for (const c of topRam) {
      const p = c.memory_percent != null ? ` (${c.memory_percent.toFixed(0)}%)` : '';
      text += `• <code>${esc(c.name)}</code>: <b>${fmtBytes(c.memory_bytes)}${p}</b>\n`;
    }
  } else {
    text += `<i>Sin datos de memoria de contenedores en este ciclo.</i>\n`;
  }
} else if (q.command === 'alerts') {
  text = `🚨 <b>RackWatch · Alertas Recientes</b>\n\n`;
  if (alerts.length) {
    for (const a of alerts.slice(0, 6)) {
      const ic = a.severity === 'critical' ? '🔴' : a.severity === 'warning' ? '⚠️' : 'ℹ️';
      text += `${ic} <b>${esc(a.title)}</b>\n` +
        (a.message ? `  ${esc(a.message)}\n` : '') +
        `  Servicio: <code>${esc(a.service || 'host')}</code> · ${esc(a.created_at ? new Date(a.created_at).toLocaleTimeString() : '')}\n\n`;
    }
  } else {
    text += `✅ No hay alertas registradas en las últimas 24 horas. Homelab saludable.`;
  }
} else {
  if (ollamaContent && !ollamaContent.includes('error')) {
    text = `🤖 <b>RackWatch · Homelab AI</b>\n\n${esc(ollamaContent.trim())}`;
  } else {
    text = `🤖 <b>RackWatch · Homelab</b>\n` +
      `Host CPU: <b>${host.cpu_percent != null ? host.cpu_percent.toFixed(0) + '%' : '—'}</b> | RAM: <b>${host.ram_percent != null ? host.ram_percent.toFixed(0) + '%' : '—'}</b>\n\n` +
      `<i>Ollama no respondió en este momento. Usa /status, /cpu, /ram o /alertas para consultar métricas directas.</i>`;
  }
}

return [{ json: { chatId: q.chatId, text: text.slice(0, 3950) } }];
